mapper.select:
SELECT id, booking_id, event_type, location_code, completion_time, memo, receive_confirmation_code, registered_at
FROM handling_events


        AND booking_id = #{bookingId}


        AND event_type = #{eventType}


        AND LOWER(location_code) LIKE LOWER(CONCAT('%', #{locationCode}, '%'))


ORDER BY completion_time DESC, id DESC
